scriptdefs
= EventScript_RockSmash
lockall
goto_if_unset FLAG_BADGE03_GET EventScript_CantSmashRock
checkpartymove MOVE_ROCK_SMASH
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CantSmashRock
setfieldeffectargument 0 VAR_RESULT
bufferpartymonnick STR_VAR_1 VAR_RESULT
buffermovename STR_VAR_2 MOVE_ROCK_SMASH
msgboxyesno	This rock appears to be breakable. Would you like to use ROCK SMASH?
goto_if_eq VAR_RESULT NO EventScript_CancelSmash
msgbox	STR_VAR_1 used STR_VAR_2!
closemessage
dofieldeffect FLDEFF_USE_ROCK_SMASH
waitstate
goto EventScript_SmashRock
end
@ Use rock smash from party menu
goto EventScript_UseRockSmash
= EventScript_UseRockSmash
lockall
dofieldeffect FLDEFF_USE_ROCK_SMASH
waitstate
goto EventScript_SmashRock
end
= EventScript_SmashRock
applymovement VAR_LAST_TALKED Movement_SmashRock
waitmovement 0
removeobject VAR_LAST_TALKED
specialvar VAR_RESULT TryUpdateRusturfTunnelState
goto_if_eq VAR_RESULT TRUE EventScript_EndSmash
special RockSmashWildEncounter
goto_if_eq VAR_RESULT FALSE EventScript_EndSmash
waitstate
releaseall
end
= EventScript_EndSmash
releaseall
end
= EventScript_CancelSmash
closemessage
releaseall
end
= EventScript_CantSmashRock
msgbox	It's a rugged rock, but a POKéMON may be able to smash it.
releaseall
end
= MirageTower_4F_EventScript_ClawFossil
lock
faceplayer
msgboxyesno	You found the CLAW FOSSIL.If this FOSSIL is taken, the ground around it will likely crumble away…Take the CLAW FOSSIL anyway?
goto_if_eq VAR_RESULT NO MirageTower_4F_EventScript_LeaveClawFossil
giveitem ITEM_CLAW_FOSSIL
closemessage
setflag FLAG_HIDE_MIRAGE_TOWER_CLAW_FOSSIL
setflag FLAG_HIDE_MIRAGE_TOWER_ROOT_FOSSIL
removeobject LOCALID_MIRAGE_CLAW_FOSSIL
delay 30
setflag FLAG_CHOSE_CLAW_FOSSIL
goto MirageTower_4F_EventScript_CollapseMirageTower
end
= MirageTower_4F_EventScript_CollapseMirageTower
setvar VAR_0x8004 1   @ vertical pan
setvar VAR_0x8005 1   @ horizontal pan
setvar VAR_0x8006 32  @ num shakes
setvar VAR_0x8007 2   @ shake delay
special ShakeCamera
waitstate
special DoMirageTowerCeilingCrumble
setvar VAR_MIRAGE_TOWER_STATE 1
clearflag FLAG_LANDMARK_MIRAGE_TOWER
warp Route111 19 59
waitstate
release
end
= MirageTower_4F_EventScript_LeaveClawFossil
msgbox	PLAYER left the CLAW FOSSIL alone.
release
end
= MirageTower_4F_EventScript_RootFossil
lock
faceplayer
msgboxyesno	You found the ROOT FOSSIL.If this FOSSIL is taken, the ground around it will likely crumble away…Take the ROOT FOSSIL anyway?
goto_if_eq VAR_RESULT NO MirageTower_4F_EventScript_LeaveRootFossil
giveitem ITEM_ROOT_FOSSIL
closemessage
setflag FLAG_HIDE_MIRAGE_TOWER_ROOT_FOSSIL
setflag FLAG_HIDE_MIRAGE_TOWER_CLAW_FOSSIL
removeobject LOCALID_MIRAGE_ROOT_FOSSIL
delay 30
setflag FLAG_CHOSE_ROOT_FOSSIL
goto MirageTower_4F_EventScript_CollapseMirageTower
end
= MirageTower_4F_EventScript_LeaveRootFossil
msgbox	PLAYER left the ROOT FOSSIL alone.
release
end
